(function(){document.addEventListener('DOMContentLoaded',function(){if(typeof go360Logs==='undefined')return;const e=document.querySelector('.dashboard__activity-feed');if(!e)return;const t=document.getElementById('logs-load-more');let n=1;const o=10;async function a(){const a=await fetch(`${go360Logs.endpoint}?page=${n}&per_page=${o}`,{headers:{'X-WP-Nonce':go360Logs.nonce}});if(!a.ok)return;const r=await a.json();if(!Array.isArray(r)||r.length===0){t&&(t.style.display='none');return}r.forEach(o=>{const n=document.createElement('div');n.className='dashboard__activity-item';const a=document.createElement('div');a.className='dashboard__activity-time';a.textContent=new Date(o.created_at).toLocaleString();const r=document.createElement('div');r.className='dashboard__activity-content';r.textContent=o.details||o.event_type;n.appendChild(a);n.appendChild(r);e.appendChild(n)});t&&(t.style.display='block')}t&&t.addEventListener('click',function(){n++;a()});a()})})();
